INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (18,18,'["Quels outils utilisez-vous concrètement pour suivre et contrôler la gestion d''un projet ou d''un budget, même à petite échelle ?", "Comment définissez-vous un indicateur de performance pertinent pour mesurer l''avancement d''un projet dans une organisation publique ?", "Si vous deviez identifier un écart entre les objectifs fixés et les résultats obtenus, quelle démarche adopteriez-vous pour analyser et corriger la situation ?", "Votre formation est en Informatique et Intelligence Artificielle — qu''est-ce qui vous a amené à vous orienter vers un poste de contrôle et gestion plutôt que vers un métier purement technique ?", "Durant votre année d''expérience, avez-vous eu à produire des rapports, des tableaux de bord ou des synthèses destinés à des responsables ? Décrivez une situation précise.", "Quelle est la compétence principale que vous avez développée depuis votre baccalauréat en 2023, et en quoi est-elle utile pour ce poste ?", "Pourquoi souhaitez-vous intégrer l''ADER Fès-Meknès aujourd''hui, et qu''est-ce que ce poste représente pour vous dans votre parcours professionnel ?", "Où vous voyez-vous dans trois ans, et comment ce poste de CGM s''inscrit-il dans votre projet professionnel à long terme ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et du rôle qu''elle joue dans le développement de la région ?", "Selon vous, quelles sont les contraintes spécifiques du travail dans un établissement public par rapport au secteur privé, et êtes-vous prêt à y faire face ?"]','[]','{}','2026-08-27 13:29:22.334015') ON CONFLICT (id) DO NOTHING;